package dev.s7a.strata.state

import dev.s7a.strata.internal.platform.EvaluationContext
import dev.s7a.strata.internal.platform.currentOwner
import dev.s7a.strata.internal.platform.withValue
import dev.s7a.strata.spi.InternalStrataRuntimeApi
import kotlin.jvm.JvmSynthetic

/**
 * Runtime-owned dependency set for one owner-confined screen evaluator.
 * Successful evaluation replaces dependencies; failed evaluation retains them until terminal cleanup.
 * Closing releases every dependency without closing the caller-owned state and is idempotent.
 *
 * @param beforeMutation validates the session phase and enters its equality/reentrancy guard; failure must leave that guard unchanged.
 * @param validateMutation checks the current operation phase without entering a mutation guard.
 * @param afterMutation leaves the guard after an accepted mutation attempt and must not throw.
 * @param invalidated marks the screen dirty after an unequal assignment and must not throw or run application code.
 */
@InternalStrataRuntimeApi
public class StateObservation(
    private val beforeMutation: () -> Unit,
    private val afterMutation: () -> Unit,
    private val invalidated: () -> Unit,
    private val validateMutation: () -> Unit,
) : AutoCloseable {
    private val owner = currentOwner()
    private val dependencies = LinkedHashSet<MutableState<*>>()
    private var collecting: MutableSet<MutableState<*>>? = null
    private var closed = false
    private var parent: StateObservation? = null
    private val children = LinkedHashSet<StateObservation>()

    // Links exist only during synchronous operations; the outermost guard owns the current tail.
    private var previousOperation: StateObservation? = null
    private var nextOperation: StateObservation? = null
    private var lastOperation: StateObservation? = null

    /**
     * Shared mutation guard identity for independently evaluated regions of one session.
     */
    internal var mutationOwner: StateObservation = this
        private set

    /**
     * Creates an independently tracked retained region sharing this session's mutation guard.
     * The region owner closes it on removal; closing this observation also releases every remaining region.
     */
    public fun fork(invalidated: () -> Unit): StateObservation {
        checkOwner()
        check(closed.not()) { "State observation is closed." }
        return StateObservation(beforeMutation, afterMutation, invalidated, validateMutation).also { child ->
            child.parent = this
            child.mutationOwner = mutationOwner
            children.add(child)
        }
    }

    /**
     * Installs this session's phase guard for all state writes under the execution owner.
     * The runtime must pair a successful call with [leaveOperation] in a finally block, including after terminal cleanup.
     * Nested operations from different sessions must leave in reverse order.
     */
    public fun enterOperation() {
        checkOwner()
        check(previousOperation == null && lastOperation == null) { "A state observation operation is already active." }
        val first = operations.current
        if (first == null) {
            operations.current = this
            lastOperation = this
        } else {
            val previous = checkNotNull(first.lastOperation)
            previousOperation = previous
            previous.nextOperation = this
            first.lastOperation = this
        }
    }

    /**
     * Removes the innermost operation guard under its execution owner.
     * This remains valid after [close] releases dependencies during terminal session cleanup.
     */
    public fun leaveOperation() {
        checkOwner()
        val first = checkNotNull(operations.current) { "No state observation operation is active." }
        check(first.lastOperation === this) { "State observation operations must leave in reverse order." }
        val previous = previousOperation
        if (previous == null) {
            lastOperation = null
            operations.current = null
        } else {
            previous.nextOperation = null
            first.lastOperation = previous
            previousOperation = null
        }
    }

    /**
     * Evaluates [content] synchronously and records exactly its state reads.
     * Requires the execution owner and a live, non-evaluating observation.
     * The result and any application failure are propagated unchanged; nested screen evaluations restore their caller's tracking context.
     */
    public fun <T> evaluate(content: () -> T): T {
        checkOwner()
        check(closed.not() && collecting == null) { "State observation is closed or already evaluating." }
        checkAccess()
        val reads = LinkedHashSet<MutableState<*>>()
        collecting = reads
        return try {
            active.withValue(this) {
                val result = content()
                dependencies.filter { (it in reads).not() }.forEach { state -> state.forget(this) }
                dependencies.retainAll(reads)
                result
            }
        } finally {
            collecting = null
        }
    }

    override fun close() {
        checkOwner()
        check(collecting == null) { "State observation cannot close during evaluation." }
        if (closed) return
        closed = true
        children.toList().forEach(StateObservation::close)
        children.clear()
        parent?.children?.remove(this)
        parent = null
        val released = dependencies.toList()
        dependencies.clear()
        released.forEach { state -> state.forget(this) }
    }

    private fun checkOwner() {
        check(currentOwner() == owner) { "State observation requires its construction execution owner." }
    }

    /**
     * Validates the owning session and enters its mutation guard.
     */
    internal fun beginMutation() = beforeMutation()

    /**
     * Leaves the owning session's mutation guard.
     */
    internal fun endMutation() = afterMutation()

    /**
     * Marks the owning session dirty without executing application code.
     */
    internal fun invalidate() = invalidated()

    /**
     * Owns dynamically scoped read tracking and equality guards for the current thread.
     */
    internal companion object {
        private val active = EvaluationContext<StateObservation>()
        private val comparing = EvaluationContext<Boolean>()
        private val operations = EvaluationContext<StateObservation>()
        private val readCapture = EvaluationContext<() -> Unit>()

        /**
         * Reports whether a synchronous callback read mutable state without changing dependency ownership.
         * Nested captures also notify their enclosing capture; every exit restores the caller's context.
         * A derived declaration must not reuse a callback result that performed such a read.
         */
        @JvmSynthetic
        internal fun <T> captureReads(content: () -> T): Pair<T, Boolean> {
            var read = false
            val enclosing = readCapture.current
            val result =
                readCapture.withValue(
                    {
                        read = true
                        enclosing?.invoke()
                    },
                    content,
                )
            return result to read
        }

        /**
         * Records a state read in the innermost screen evaluation on this thread.
         */
        internal fun record(state: MutableState<*>) {
            readCapture.current?.invoke()
            val observation = active.current ?: return
            checkNotNull(observation.collecting).add(state)
            if (observation.dependencies.add(state)) state.observe(observation)
        }

        /**
         * Rejects state access from arbitrary user equality code.
         */
        internal fun checkAccess() {
            check(comparing.current != true) { "State access is forbidden during equality comparison." }
        }

        /**
         * Rejects writes during declarative screen evaluation.
         */
        internal fun checkMutation() {
            check(active.current == null) { "State mutation is forbidden during screen evaluation." }
            var observation = operations.current
            while (observation != null) {
                observation.validateMutation()
                observation = observation.nextOperation
            }
        }

        /**
         * Executes caller equality under a scoped guard, restoring it even after failure.
         */
        internal fun compare(equality: () -> Boolean): Boolean {
            checkAccess()
            return comparing.withValue(true, equality)
        }
    }
}
